    88  bool CheckTag(uint32_t tag_value) {
    89    for (unsigned i = 0; i < 4; ++i) {
    90      const uint32_t check = tag_value & 0xff;
    91      if (check < 32 || check > 126) {
    92        return false;  // non-ASCII character found.
    93      }
    94      tag_value >>= 8;
    95    }
    96    return true;
    97  }
