   167  bool ValidateVersionTag(ots::Font *font) {
   168    switch (font->version) {
   169      case 0x000010000:
   170      case OTS_TAG('O','T','T','O'):
   171        return true;
   172      case OTS_TAG('t','r','u','e'):
   173        font->version = 0x000010000;
   174        return true;
   175      default:
   176        return false;
   177    }
   178  }
